import { type Held, hold, isRowKey, shifts } from './render'
import {
  type ArmEvent,
  type Arming,
  arm,
  DISARMED,
  layout,
  type Model,
  type Piece,
  type Selection,
  type Size,
  targetsOf,
} from './view'
import { fallbackOf, paneView, seatsRows } from './views/pane'

export type Shift = { key: string; isAsked: boolean; tries: number }
type Seat = { placement: string; isFocused: boolean }
export type Interaction = {
  arming: Arming
  ringOn?: string
  landedOn?: string
  aimOn?: string
  landingFrom?: string
  queued?: { key: string | undefined; move: DeferredFocus }
  shift?: Shift
  seats: Record<string, Seat>
  holds: Record<string, { scope: string; keys: Held[] }>
  pressing: number
  surface?: string
  opening?: { isAsked: boolean; tries: number }
}

export const IDLE: Interaction = { arming: DISARMED, seats: {}, holds: {}, pressing: 0 }
export const REGAIN_MS = 100

export const scopeOf = (sel: Selection): string =>
  JSON.stringify([sel.tab, sel.open, sel.query, sel.folded, sel.window?.hours, sel.grouping])

export const heldOf = (state: Interaction, surface: string, sel: Selection): Held[] | undefined => {
  const mine = state.holds[surface]
  return mine?.scope === scopeOf(sel) ? mine.keys : undefined
}

export type InteractionEvent =
  | ArmEvent
  | { type: 'opened' | 'closed' | 'press-start' | 'press-end' | 'unfocused' }
  | { type: 'render'; model: Model; size: Size; selection: Selection; placement: string }
  | { type: 'focus-start'; key: string }
  | { type: 'focus-queued'; key: string | undefined; move: DeferredFocus }
  | { type: 'refocused'; isOpen: boolean; isFocused: boolean }
  | { type: 'regained'; want: Shift; isMoved: boolean }
  // A timer's focus call on reopen landed on `key`; no focus hook ran.
  | { type: 'restored'; key: string }
  | {
      type: 'draw'
      surface: string
      placement: string
      isFocused: boolean
      scope: string
      pieces: Piece[]
      inPlace: boolean
    }

export type Effect =
  | { type: 'refocus'; after: number }
  | { type: 'regain'; want: Shift }
  | { type: 'redraw' }

export function interact(
  state: Interaction,
  event: InteractionEvent,
): { state: Interaction; effects: Effect[]; list?: Piece[] } {
  const effects: Effect[] = []
  switch (event.type) {
    case 'render': {
      const { model, size, selection } = event
      const armed = paneView(model, size, { ...selection, isArmed: true, isListArmed: true })
      const arming = arm(state.arming, {
        type: 'drawn',
        fallback: fallbackOf(model, selection),
        targets: targetsOf(armed),
        selected: selection.selected,
      })
      const drawn =
        arming.isArmed && arming.isListArmed
          ? armed
          : paneView(model, size, { ...selection, ...arming })
      return interact(
        { ...state, arming },
        {
          type: 'draw',
          surface: size.surface,
          placement: event.placement,
          isFocused: selection.isFocused,
          scope: scopeOf(selection),
          pieces: layout(drawn),
          inPlace: seatsRows(selection),
        },
      )
    }
    case 'opened':
      return {
        state: {
          ...state,
          arming: DISARMED,
          ringOn: undefined,
          landedOn: undefined,
          aimOn: undefined,
          landingFrom: undefined,
          queued: undefined,
          shift: undefined,
          holds: {},
          opening: { isAsked: true, tries: 1 },
        },
        effects: [{ type: 'refocus', after: 50 }],
      }
    case 'closed':
      return { state: { ...IDLE, pressing: state.pressing }, effects }
    case 'refocused': {
      if (!state.opening) return { state, effects }
      const opening =
        event.isOpen && !event.isFocused && state.opening.tries < 40
          ? { ...state.opening, isAsked: false }
          : undefined
      if (opening) effects.push({ type: 'redraw' })
      return { state: { ...state, opening }, effects }
    }
    case 'unfocused':
      return {
        state: {
          ...state,
          ringOn: undefined,
          landedOn: undefined,
          aimOn: undefined,
          landingFrom: undefined,
          queued: undefined,
          shift: undefined,
        },
        effects,
      }
    case 'press-start':
      return {
        state: {
          ...state,
          pressing: state.pressing + 1,
          landingFrom: state.pressing ? state.landingFrom : undefined,
        },
        effects,
      }
    case 'press-end':
      return { state: { ...state, pressing: state.pressing - 1 }, effects }
    case 'focus-start':
      return {
        state: { ...state, landedOn: undefined, aimOn: event.key, queued: undefined },
        effects,
      }
    case 'focus-queued':
      return { state: { ...state, queued: { key: event.key, move: event.move } }, effects }
    case 'landed':
      return { state: { ...state, aimOn: undefined, arming: arm(state.arming, event) }, effects }
    case 'regained':
      if (state.shift !== event.want) return { state, effects }
      return {
        state: event.isMoved
          ? { ...state, shift: undefined }
          : {
              ...state,
              shift: { ...event.want, isAsked: false },
              arming: arm(state.arming, { type: 'landed', isMoved: false }),
            },
        effects,
      }
    case 'restored':
      return {
        state: { ...state, ringOn: event.key, landedOn: event.key, shift: undefined },
        effects,
      }
    case 'draw': {
      const seat = state.seats[event.surface]
      const before = state.holds[event.surface]
      const held = before?.scope === event.scope ? before.keys : undefined
      const out = hold(event.pieces, held, event.inPlace)
      let shift = state.shift
      if (held && shifts(held, out.held, state.ringOn) && state.ringOn) {
        // Rows that come and go keep moving the ring: the tries stay bounded.
        const tries = state.shift?.key === state.ringOn ? state.shift.tries : 0
        shift = { key: state.ringOn, isAsked: false, tries }
      }
      if (shift && seat && !seat.isFocused && event.isFocused) shift = { ...shift, tries: 0 }
      // A ring row that left has no key to regain: its presses stay held back.
      const isHeld = out.held.some(one => one.key === shift?.key)
      if (shift && isHeld && !shift.isAsked && shift.tries < 3 && event.isFocused) {
        shift = { ...shift, isAsked: true, tries: shift.tries + 1 }
        effects.push({ type: 'regain', want: shift })
      }
      let opening = event.isFocused ? undefined : state.opening
      if (opening && !opening.isAsked) {
        opening = { isAsked: true, tries: opening.tries + 1 }
        effects.push({ type: 'refocus', after: 50 })
      } else if (seat?.isFocused && seat.placement !== event.placement) {
        effects.push({ type: 'refocus', after: 500 })
      }
      return {
        state: {
          ...state,
          shift,
          opening,
          holds: { ...state.holds, [event.surface]: { scope: event.scope, keys: out.held } },
          surface: event.isFocused ? event.surface : state.surface,
          seats: {
            ...state.seats,
            [event.surface]: { placement: event.placement, isFocused: event.isFocused },
          },
        },
        effects,
        list: out.list,
      }
    }
    case 'reset':
      return {
        state: {
          ...state,
          arming: DISARMED,
          ringOn: undefined,
          landedOn: undefined,
          aimOn: undefined,
          queued: undefined,
          landingFrom: state.pressing ? (state.ringOn ?? state.landingFrom) : undefined,
          shift: undefined,
        },
        effects,
      }
    case 'focus':
      return {
        state: {
          ...state,
          arming: arm(state.arming, event),
          ringOn: event.key,
          queued: undefined,
          landingFrom:
            event.byPerson || event.key === state.arming.step
              ? undefined
              : event.key === state.ringOn
                ? state.landingFrom
                : (state.ringOn ?? state.landingFrom),
          aimOn: undefined,
          landedOn: event.key,
          shift: undefined,
        },
        effects,
      }
    default:
      return { state: { ...state, arming: arm(state.arming, event) }, effects }
  }
}

export const isHeldBack = (state: Interaction, at: { surface: string; element: string }): boolean =>
  state.shift !== undefined && state.seats[at.surface]?.isFocused === true && isRowKey(at.element)

export type DeferredFocus = { by: number } | { key: string | undefined }

// The engine computes an all-fit arrow against the old tree before a press lands.
export function deferredFocus(
  state: Interaction,
  keys: readonly string[],
  key: string | undefined,
): DeferredFocus | undefined {
  if (!state.pressing && !keys.includes(state.landingFrom ?? '')) return undefined
  if (state.queued && state.queued.key === key) return state.queued.move
  const from = keys.indexOf(state.ringOn ?? '')
  const aim = keys.indexOf(state.aimOn ?? '')
  const to = keys.indexOf(key ?? '')
  const before = keys.indexOf(state.landingFrom ?? '')
  const origins = state.queued ? [keys.indexOf(state.queued.key ?? '')] : [aim, from, before]
  for (const origin of origins) {
    if (origin < 0 || to < 0) continue
    const by = to - origin
    if (!state.queued && origin === from && by === 0) return { by: 0 }
    if (Math.abs(by) === 1) return { by }
    if (keys.length > 2 && Math.abs(by) === keys.length - 1) return { by: by > 0 ? -1 : 1 }
  }
  return state.pressing ? { key } : undefined
}

export function movedFocus(
  state: Interaction,
  keys: readonly string[],
  move: DeferredFocus,
): string | undefined {
  if ('key' in move) return move.key
  const from = keys.indexOf(state.ringOn ?? '')
  if (from < 0 || keys.length === 0) return undefined
  return keys[(((from + move.by) % keys.length) + keys.length) % keys.length]
}

files.hooks/ui/lists.ts:
import type { RabeEdit, RabeMainUsage, RabeOrder, RabePrevious } from '../../types'
import {
  firstCodexOf,
  isEnded,
  itemById,
  KINDS,
  type RabeItem,
  type RabeItemKind,
  runOf,
} from '../model'
import { nextRuns } from '../schedule'
import { mainTotal } from './groups'
import { byConflict, touched } from './touched'

export { touched, treeOf, worktreeRows } from './touched'

import type { Span } from './cells/grid'
import { C, type Style } from './cells/palette'
import { ago, clockTime, duration, short, tokens, usd } from './format'

export type Group = 'failed' | 'agents' | 'shells' | 'monitors' | 'cron'

const GROUPS: { id: Group; label: string }[] = [
  { id: 'failed', label: 'Failed' },
  { id: 'agents', label: 'Agents' },
  { id: 'shells', label: 'Shells' },
  { id: 'monitors', label: 'Monitors' },
  { id: 'cron', label: 'Cron' },
]

export const KIND_LABEL: Record<RabeItemKind, string> = {
  agent: 'claude',
  codex: 'codex',
  workflow: 'workflow',
  shell: 'shell',
  monitor: 'monitor',
  cron: 'cron',
}

const RUNNING_GLYPH: Record<RabeItemKind, string> = {
  agent: '◐',
  codex: '◐',
  workflow: '⧉',
  shell: '▶',
  monitor: '◉',
  cron: '⟳',
}

export function glyph(item: RabeItem): string {
  if (item.status === 'failed') return '✗'
  if (item.status === 'done') return '✓'
  if (item.status === 'stopped') return '■'
  if (item.status === 'idle') return '◷'

  return RUNNING_GLYPH[kindOf(item)]
}

export function statusLabel(item: RabeItem): string {
  return item.kind === 'cron' && item.detail.isDeleted ? 'deleted' : item.status
}

function nextRun(item: RabeItem, now: number): number | undefined {
  if (item.kind !== 'cron') return undefined
  if (item.detail.scheduledFor !== undefined) return item.detail.scheduledFor

  return item.detail.schedule ? nextRuns(item.detail.schedule, now, 1)[0] : undefined
}

// The next run as its clock time: a countdown in m:ss (`15:44`) reads like
// one. A wakeup past its time waits for the session to go idle: `due`.
export function nextAt(item: RabeItem, now: number): string {
  const next = nextRun(item, now)
  if (next === undefined) return 'n/a'

  return next > now ? clockTime(next).slice(0, 5) : 'due'
}

// A shell's port (blue) and a failed shell's exit code (red) follow its title.
export function nameSpans(item: RabeItem, style: Style = {}): Span[] {
  const out: Span[] = [[item.title, style]]
  if (item.kind !== 'shell') return out
  if (item.detail.port !== undefined) out.push([` :${item.detail.port}`, { fg: C.blue }])
  if (item.status === 'failed' && item.detail.exitCode !== undefined) {
    out.push([` exit ${item.detail.exitCode}`, { fg: C.red }])
  }

  return out
}

export function timeLabel(item: RabeItem, now: number): string {
  if (isEnded(item)) return item.endedAt === undefined ? 'n/a' : ago(now - item.endedAt)
  if (item.kind === 'cron') {
    const at = nextAt(item, now)
    return at === 'n/a' || at === 'due' ? at : `next ${at}`
  }
  if (item.startedAt === undefined) return `≥ ${short(now - item.seenAt)}`

  return duration(now - item.startedAt)
}

function groupOf(item: RabeItem): Group {
  return item.status === 'failed' ? 'failed' : kindGroupOf(item)
}

// A shell row whose command is a direct `codex exec`: it lives with the Agents.
export const isCodexRun = (item: RabeItem): boolean =>
  item.kind === 'shell' && item.detail.codex !== undefined

// The kind a row is counted and labelled as: a direct Codex run is `codex`.
export const kindOf = (item: RabeItem): RabeItemKind => (isCodexRun(item) ? 'codex' : item.kind)

// The group of an item's kind, whatever its status.
function kindGroupOf(item: RabeItem): Group {
  if (isCodexRun(item)) return 'agents'
  if (item.kind === 'shell') return 'shells'
  if (item.kind === 'monitor') return 'monitors'
  if (item.kind === 'cron') return 'cron'

  return 'agents'
}

// The items the Items list and the band's chips show: the person removed the
// others this session (`rabe.removed`). Other views keep them. An item that runs again shows, since nothing
// running or idle is ever hidden.
export const kept = (items: RabeItem[], removed: readonly string[] = []): RabeItem[] =>
  removed.length === 0 ? items : items.filter(item => !isEnded(item) || !removed.includes(item.id))

export function matches(item: RabeItem, query: string): boolean {
  const q = query.trim().toLowerCase()
  if (!q) return true
  const d = item.detail as Record<string, unknown>
  const words = [item.title, KIND_LABEL[kindOf(item)], d.command, d.prompt, d.description, d.type]

  return words.some(word => typeof word === 'string' && word.toLowerCase().includes(q))
}

// A Claude agent that only forwarded work to the Codex companion: each tool
// call it made ran the companion, and Rabe linked a job to it. Its row folds
// into the job; an agent that did more, or whose tool count is not known, stays.
function isForwarder(item: RabeItem, items: readonly RabeItem[]): boolean {
  if (item.kind !== 'agent') return false
  const calls = item.detail.codexCalls?.length ?? 0

  return calls > 0 && item.detail.toolCount === calls && firstCodexOf(items, item.id) !== undefined
}

// The items lists show: forwarders fold into their Codex jobs.
export const shown = (items: RabeItem[]): RabeItem[] =>
  items.filter(item => !isForwarder(item, items))

// The forwarder folded into a Codex job: only its first job counts it.
export function forwarderOf(job: RabeItem, items: readonly RabeItem[]): RabeItem | undefined {
  if (job.kind !== 'codex' || !job.parentId) return undefined
  const parent = itemById(items, job.parentId)
  const first = firstCodexOf(items, job.parentId)

  return parent && first === job && isForwarder(parent, items) ? parent : undefined
}

// The row that stands for item `id`: a folded forwarder's is its job's.
export function rowOf(id: string, items: readonly RabeItem[]): string {
  const parent = itemById(items, id)
  const job = firstCodexOf(items, id)

  return job && parent && isForwarder(parent, items) ? job.id : id
}

const both = (a?: number, b?: number) => (a === undefined || b === undefined ? undefined : a + b)

// A Codex job's spend with its forwarder's: one piece of work, one cost line.
// What one of them lacks makes the sum unknown, never the other's part.
export function withForwarder(item: RabeItem, items: readonly RabeItem[]): RabeItem {
  const by = forwarderOf(item, items)
  if (!by) return item
  const [a, b] = [item.tokens, by.tokens]
  const cached = both(a?.cached, b?.cached)
  const tokens =
    a && b
      ? {
          input: a.input + b.input,
          output: a.output + b.output,
          ...(cached !== undefined && { cached }),
        }
      : undefined

  return { ...item, tokens, costUsd: both(item.costUsd, by.costUsd) } as RabeItem
}

// Codex jobs follow the agent that started them, after its other jobs. A job
// in `held` (the order the pane opened with) keeps its place.
function nest(list: RabeItem[], held: readonly string[] = []): RabeItem[] {
  const isHeld = new Set(held)
  const agents = new Set(list.filter(item => item.kind === 'agent').map(item => item.id))
  const isChild = (item: RabeItem) =>
    item.kind === 'codex' && !isHeld.has(item.id) && agents.has(item.parentId ?? '')
  const kids = new Map<string, RabeItem[]>()
  for (const item of list) {
    if (item.parentId === undefined || !isChild(item)) continue
    const own = kids.get(item.parentId) ?? []
    own.push(item)
    kids.set(item.parentId, own)
  }
  const rest = list.filter(item => !isChild(item))
  const owner = (item?: RabeItem) => (item?.kind === 'codex' && item.parentId) || item?.id
  const placed = new Set<string | undefined>()

  return rest.flatMap((item, i) => {
    const id = owner(item)
    if (owner(rest[i + 1]) === id || placed.has(id)) return [item]
    placed.add(id)
    return [item, ...(kids.get(id ?? '') ?? [])]
  })
}

const recency = (item: RabeItem) => item.endedAt ?? item.startedAt ?? item.seenAt

function sortItems(items: RabeItem[]): RabeItem[] {
  return items.toSorted(
    (a, b) => Number(!isEnded(b)) - Number(!isEnded(a)) || recency(b) - recency(a),
  )
}

// A list that does not reorder under the focus. Without `held` (nobody has
// seen the list yet) it is `sort(list)`; with it, the held ids come first in
// held order, then the others in the order of `list`, which is the order Rabe
// saw them: new items append, and a status change moves nothing.
export function stable<T extends { id: string }>(
  list: T[],
  held: readonly string[] | undefined,
  sort: (list: T[]) => T[],
): T[] {
  if (!held) return sort(list)
  const at = new Map(held.map((id, i) => [id, i]))

  return list.toSorted((a, b) => (at.get(a.id) ?? held.length) - (at.get(b.id) ?? held.length))
}

// The Items tab's groups, failed first. Without `order` each group sorts
// running and idle first, then the newest; with it, a held item stays in the group and
// place `orderOf` gave it, and an item Rabe saw since goes to the group of its
// kind (failed or not, so it never changes group), after the held rows, in
// the order Rabe saw it. The pane moves the focus ring back onto its row when
// such a row comes above it (see `hold` in render.tsx).
export function grouped(
  items: RabeItem[],
  order?: RabeOrder,
): { id: Group; label: string; items: RabeItem[] }[] {
  // The first group whose held ids hold the item, as a lookup.
  const heldIn = new Map<string, Group>()
  if (order) {
    for (const group of GROUPS) {
      for (const id of order[group.id] ?? []) if (!heldIn.has(id)) heldIn.set(id, group.id)
    }
  }
  const of = (item: RabeItem): Group =>
    order ? (heldIn.get(item.id) ?? kindGroupOf(item)) : groupOf(item)

  return GROUPS.map(group => {
    const held = order && (order[group.id] ?? [])
    const list = stable(
      items.filter(item => of(item) === group.id),
      held,
      sortItems,
    )
    return { ...group, items: group.id === 'agents' ? nest(list, held) : list }
  }).filter(group => group.items.length > 0)
}

const start = (item: RabeItem) => item.startedAt ?? item.seenAt

export function byStart(items: RabeItem[]): RabeItem[] {
  return items.toSorted((a, b) => start(a) - start(b))
}

// Shells and monitors an agent started sit under that agent (see `byParent`).
export const FAMILIES: Group[] = ['shells', 'monitors']

// The order the pane shows when it opens: each group sorted (shells and
// monitors in their families), the Cost tab by tokens, the Timeline by start,
// the Effects files by `byConflict` and its ports (the shells that run with
// one). Held in `rabe.order` until the next open.
export function orderOf(
  all: RabeItem[],
  edits: RabeEdit[] = [],
  main?: Record<string, RabeMainUsage>,
): RabeOrder {
  const ids = (list: RabeItem[]) => list.map(item => item.id)
  const items = shown(all)

  return {
    ports: ids(
      items.filter(
        item =>
          item.kind === 'shell' && item.detail.port !== undefined && item.status === 'running',
      ),
    ),
    ...Object.fromEntries(
      grouped(items).map(group => [
        group.id,
        ids(
          FAMILIES.includes(group.id)
            ? byParent(group.items, items).flatMap(family => family.items)
            : group.items,
        ),
      ]),
    ),
    cost: costIds(
      items.map(item => withForwarder(item, all)),
      main,
    ),
    timeline: ids(byStart(items)),
    files: byConflict(touched(all, edits)).map(file => file.id),
  }
}

// The Cost tab's agent rows by tokens; the main session's row sorts with the workers.
const costIds = (workers: RabeItem[], main?: Record<string, RabeMainUsage>): string[] => {
  const total = mainTotal('agent', main ?? {})
  const rows = [
    ...byTokens(workers).map(item => ({ id: item.id, tokens: tokenSum(item) })),
    ...(total ? [total] : []),
  ]

  return rows.toSorted((a, b) => b.tokens - a.tokens).map(row => row.id)
}

export type Family = { id: string; parent?: RabeItem; title: string; items: RabeItem[] }

// Shells and monitors by who started them: the main session's first (title
// ''), then one block per agent in the order of `list`. A workflow agent reads
// "run › agent"; an agent Rabe no longer holds "agent n/a".
export function byParent(list: RabeItem[], items: RabeItem[]): Family[] {
  const blocks: Family[] = [{ id: '', title: '', items: [] }]
  const at = new Map<string, Family>([['', blocks[0] as Family]])
  for (const item of list) {
    const id = item.parentId ?? ''
    let block = at.get(id)
    if (!block) {
      const parent = itemById(items, id)
      const run = parent && runOf(parent, items)
      const title = !parent ? 'agent n/a' : run ? `${run.title} › ${parent.title}` : parent.title
      block = { id, ...(parent && { parent }), title, items: [] }
      blocks.push(block)
      at.set(id, block)
    }
    block.items.push(item)
  }

  return blocks.filter(block => block.items.length > 0)
}

export function groupNote(id: Group, items: RabeItem[]): string {
  if (id === 'failed') return ''
  const running = items.filter(item => item.status === 'running').length
  const ended = items.filter(isEnded).length
  const idle = items.filter(item => item.status === 'idle').length
  const state = [running && `${running} running`, idle && `${idle} idle`, ended && `${ended} ended`]
    .filter(Boolean)
    .join(' · ')
  if (id === 'agents') {
    const kinds = (['agent', 'codex', 'workflow'] as const)
      .map(kind => [items.filter(item => kindOf(item) === kind).length, KIND_LABEL[kind]] as const)
      .filter(([count]) => count > 0)
      .map(([count, label]) => `${count} ${label}`)
      .join(' · ')
    return [state, kinds].filter(Boolean).join(' · ')
  }
  return state
}

export function children(items: RabeItem[], id: string): RabeItem[] {
  return items.filter(item => item.parentId === id)
}

type PhaseState = 'done' | 'running' | 'failed' | 'waiting'

export function phases(
  items: RabeItem[],
  flow: RabeItem,
): { name: string; state: PhaseState; agents: RabeItem[] }[] {
  if (flow.kind !== 'workflow') return []
  const agents = children(items, flow.id)
  const names = flow.detail.phases ?? []
  const seen = agents.map(a => (a.kind === 'agent' ? a.detail.workflowPhase : undefined) ?? 'n/a')
  const all = [
    ...names,
    ...seen.filter((one, i) => !names.includes(one) && seen.indexOf(one) === i),
  ]

  return all.map(phase => {
    const list = agents.filter((_, i) => seen[i] === phase)
    const state: PhaseState =
      list.length === 0
        ? 'waiting'
        : list.some(a => a.status === 'running')
          ? 'running'
          : list.every(a => a.status === 'done')
            ? 'done'
            : 'failed'
    return { name: phase, state, agents: list }
  })
}

export function phaseProgress(items: RabeItem[], flow: RabeItem): string {
  const list = phases(items, flow)
  const at = list.findLastIndex(phase => phase.state !== 'waiting')
  if (at === -1) return list.length ? `0/${list.length}` : 'n/a'

  return `${list[at]?.name} ${at + 1}/${list.length}`
}

type Totals = {
  usd?: number
  tokens: number
  unknown: number
  claude?: number
  codex?: number
}

// The workers that spend: Claude agents and Codex jobs.
export const isWorker = (item: RabeItem) => kindOf(item) === 'agent' || kindOf(item) === 'codex'

export const harnessOf = (item: RabeItem): 'claude' | 'codex' =>
  kindOf(item) === 'agent' ? 'claude' : 'codex'

export type Spend = {
  input: number
  output: number
  cached: number
  // items with token data, and items without it
  known: number
  unknown: number
  // undefined when no item is given or one has no dollar amount: that item
  // makes the sum unknown, not smaller
  usd?: number
}

export function spend(items: readonly RabeItem[]): Spend {
  const out: Spend = { input: 0, output: 0, cached: 0, known: 0, unknown: 0 }
  for (const item of items) {
    if (item.tokens) {
      out.known += 1
      out.input += item.tokens.input
      out.output += item.tokens.output
      out.cached += item.tokens.cached ?? 0
    } else out.unknown += 1
  }
  if (items.length && items.every(item => item.costUsd !== undefined)) {
    out.usd = items.reduce((n, item) => n + (item.costUsd ?? 0), 0)
  }

  return out
}

export function spendBy<K>(items: readonly RabeItem[], keyOf: (item: RabeItem) => K) {
  const groups = new Map<K, RabeItem[]>()
  for (const item of items) {
    const key = keyOf(item)
    const own = groups.get(key) ?? []
    own.push(item)
    groups.set(key, own)
  }

  return new Map([...groups].map(([key, group]) => [key, spend(group)]))
}

export function totals(items: RabeItem[]): Totals {
  const workers = items.filter(isWorker)
  const all = spend(workers)
  const by = spendBy(workers, harnessOf)
  const out: Totals = { tokens: all.input + all.output, unknown: all.unknown }
  if (all.usd !== undefined) out.usd = all.usd
  for (const side of ['claude', 'codex'] as const) {
    const usd = by.get(side)?.usd
    if (usd !== undefined) out[side] = usd
  }

  return out
}

export const cost = (n: number | undefined) => (n === undefined ? 'n/a' : `≈ ${usd(n)}`)

export const tokenSum = (item: RabeItem) =>
  item.tokens ? item.tokens.input + item.tokens.output : -1

export function byTokens(items: RabeItem[]): RabeItem[] {
  return items.filter(isWorker).toSorted((a, b) => tokenSum(b) - tokenSum(a))
}

export function share(items: RabeItem[], item: RabeItem): string {
  const all = totals(items).tokens
  const own = tokenSum(item)

  return all > 0 && own >= 0 ? `${Math.round((own / all) * 100)}%` : 'n/a'
}

// `session` is the session's cost as `/cost` totals it; it wins over the sum
// of the items, which misses every worker without a dollar amount.
export function costLine(items: RabeItem[], session?: number): string | undefined {
  const sum = totals(items)
  if (sum.tokens === 0) return undefined
  const dollars = session === undefined ? 'n/a' : `≈ ${usd(session)}`
  const cached = items.reduce((n, item) => n + (item.tokens?.cached ?? 0), 0)
  const cacheText =
    sum.tokens > 0 && cached > 0 ? `, ${Math.round((cached / sum.tokens) * 100)}% cached` : ''

  return `session ${dollars} · bg ${tokens(sum.tokens)} tok${cacheText}`
}

export type BandRow = { glyph: string; kind: RabeItemKind; count: number; failed?: boolean }

// What the band counts per kind, failed (in the last 10 minutes) first.
export function bandRows(items: RabeItem[], now: number): BandRow[] {
  const running = (kind: RabeItemKind) =>
    shown(items).filter(item => kindOf(item) === kind && item.status === 'running').length
  const failed = KINDS.flatMap(kind => {
    const count = items.filter(
      item =>
        kindOf(item) === kind &&
        item.status === 'failed' &&
        now - (item.endedAt ?? item.seenAt) < 10 * 60_000,
    ).length
    return count ? [{ glyph: '✗', kind, count, failed: true }] : []
  })
  const rows: BandRow[] = [
    ...failed,
    ...KINDS.map(kind => ({
      glyph: RUNNING_GLYPH[kind],
      kind,
      count: running(kind),
    })),
  ]

  return rows.filter(row => row.failed || row.count > 0)
}

type TreeLine = { prefix: string; item: RabeItem }

export function tree(items: RabeItem[]): TreeLine[] {
  const ids = new Set(items.map(item => item.id))
  const kids = new Map<string, RabeItem[]>()
  for (const item of items) {
    if (item.parentId === undefined) continue
    const own = kids.get(item.parentId) ?? []
    own.push(item)
    kids.set(item.parentId, own)
  }
  const out: TreeLine[] = []
  const walk = (list: RabeItem[], indent: string) => {
    for (const [i, item] of list.entries()) {
      const isLast = i === list.length - 1
      out.push({ prefix: `${indent}${isLast ? '└─ ' : '├─ '}`, item })
      walk(kids.get(item.id) ?? [], `${indent}${isLast ? '   ' : '│  '}`)
    }
  }
  walk(
    items.filter(item => !item.parentId || !ids.has(item.parentId)),
    '',
  )

  return out
}

export function bar(from: number, to: number, start: number, end: number, width: number): string {
  const span = Math.max(1, end - start)
  const a = Math.min(width - 1, Math.max(0, Math.floor(((from - start) / span) * width)))
  const b = Math.max(a + 1, Math.min(width, Math.ceil(((to - start) / span) * width)))

  return `${' '.repeat(a)}${'█'.repeat(b - a)}${' '.repeat(width - b)}`
}

// What the next session in this project shows of this one.
export function previousOf(
  items: RabeItem[],
  endedAt: number,
  usage: { startedAt?: number; usd?: number },
  sessionId?: string,
): RabePrevious {
  const counts: RabePrevious['counts'] = {}
  for (const item of items) {
    if (item.kind === 'cron' && item.status !== 'running') continue
    counts[item.kind] = (counts[item.kind] ?? 0) + 1
  }

  return {
    ...(sessionId && { sessionId }),
    endedAt,
    startedAt: usage.startedAt,
    counts,
    tokens: totals(items).tokens,
    usd: usage.usd,
    failedIds: items.filter(item => item.status === 'failed').map(item => item.id),
  }
}

