const pad = (n: number) => String(n).padStart(2, '0')

export function validId(id: string | undefined): id is string {
  return id !== undefined && /^[A-Za-z0-9_][A-Za-z0-9_.-]*$/.test(id)
}

export function duration(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m${pad(s % 60)}s`

  return `${Math.floor(s / 3600)}h${pad(Math.floor(s / 60) % 60)}m`
}

export function short(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m`

  return duration(ms)
}

export function ago(ms: number): string {
  const s = Math.floor(ms / 1000)
  if (s < 10) return 'just now'
  if (s < 3600) return `${short(ms)} ago`

  return `${Math.floor(s / 3600)}h ago`
}

export function clockTime(ms: number): string {
  const d = new Date(ms)

  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`
}

export function tokens(n: number): string {
  if (n < 1000) return String(n)
  if (n < 1_000_000) return `${Math.round(n / 1000)}k`

  return `${(n / 1_000_000).toFixed(1)}M`
}

export function usd(n: number): string {
  return `$${n.toFixed(2)}`
}

// The text as it is, or cut to `room` characters with a last `…`.
export function cut(text: string, room: number): string {
  const chars = [...text]

  return chars.length > room ? `${chars.slice(0, room - 1).join('')}…` : text
}

// A value for a fact line: `n/a` where it is unknown or empty.
export const na = (value: unknown) => (value === undefined || value === '' ? 'n/a' : String(value))

// An agent, thread or session id, or `n/a` when it is not a safe id.
export const idOrNa = (id: string | undefined) => (validId(id) ? id : 'n/a')

export function middleEllipsis(value: string, width: number): string {
  const chars = [...value]
  if (chars.length <= width) return value
  const left = Math.ceil((width - 1) / 2)
  const right = Math.floor((width - 1) / 2)
  return `${chars.slice(0, left).join('')}…${right ? chars.slice(-right).join('') : ''}`
}

export function day(ms: number, now: number): string {
  const d = new Date(ms)
  const today = new Date(now)
  const midnight = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()
  const before = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1).getTime()
  const time = clockTime(ms).slice(0, 5)
  if (ms >= midnight) return `today ${time}`
  if (ms >= before) return `yesterday ${time}`

  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${time}`
}

